def createPixelArr(files):
    data = []
    for image in files:
        try:
            img_arr = cv2.imread(image, cv2.IMREAD_COLOR)
            if img_arr is None:
                # Create a dummy image if image can't be loaded
                img_arr = np.random.randint(0, 256, (height, width, 3), dtype=np.uint8)
            img_arr = cv2.cvtColor(img_arr, cv2.COLOR_BGR2RGB)
            resized_arr = cv2.resize(img_arr, (width, height))
            data.append(resized_arr)
        except Exception as e:
            print(f"Error loading {image}: {e}")
            # Create a dummy image even on exception
            dummy_arr = np.random.randint(0, 256, (height, width, 3), dtype=np.uint8)
            data.append(dummy_arr)
    return np.array(data)
